'use strict';
/* VYZO ACADEMY — aplicação estática, sem envio de respostas a servidores. */
(()=>{
const STORE='enem-intelligence-v2', OLD='enem-intelligence-v1';
const NEW=Array.isArray(window.QUESTION_BANK)?window.QUESTION_BANK:[];
const LEGACY=Array.isArray(window.LEGACY_BANK)?window.LEGACY_BANK:[];
const BANK=new Map([...LEGACY,...NEW].map(q=>[q.id,q]));
const AREAS=['Linguagens','Humanas','Natureza','Matemática'];
const areaNames={Linguagens:'Linguagens, Códigos e suas Tecnologias',Humanas:'Ciências Humanas e suas Tecnologias',Natureza:'Ciências da Natureza e suas Tecnologias',Matemática:'Matemática e suas Tecnologias'};
const A=['A','B','C','D','E'];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtTime=s=>{s=Math.max(0,Math.floor(s));return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`};
const fmtDate=ms=>new Date(ms||Date.now()).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'});
const unique=arr=>[...new Set(arr)];
const COUNTS=Array.from({length:10},(_,i)=>(i+1)*10);
const defaultCfg=()=>({mode:'diagnostic',area:'Todas',subject:'Todas',topic:'Todos',count:20,language:'Inglês',timed:false,minutes:90});
const initial=()=>({schema:2,theme:'light',config:defaultCfg(),exam:null,history:[],seenIds:[],essay:{text:'',notes:''},mentor:{version:1},preferences:{examLarge:false},lastPage:'home'});
let state=initial(), route='home', ticker=null, legacyAvailable=null, storageMode='none', storageNote='', pendingExternal=false, mapFilter='all', lastSavedAt=0, announcedTimes=new Set();
const validQuestions=NEW.filter(q=>q&&q.id&&q.context&&q.stem&&q.options?.length===5&&Number.isInteger(q.answer)&&q.answer>=0&&q.answer<5);
function persist(){
  if(pendingExternal){storageMode='conflict';storageNote='Outra aba alterou seus dados — exporte um backup';setPill();return false}
  const payload=JSON.stringify({...state,savedAt:Date.now()});
  let done=false;
  try{localStorage.setItem(STORE,payload);done=true;storageMode='local';storageNote='Respostas salvas automaticamente'}catch(e){}
  try{sessionStorage.setItem(STORE,payload);if(!done){done=true;storageMode='session';storageNote='Salvo só nesta sessão — exporte um backup'}}catch(e){}
  if(!done){storageMode='memory';storageNote='Sem salvamento persistente — exporte um backup'};
  if(done)lastSavedAt=Date.now();setPill();return done;
}
function setPill(){const el=$('#save-pill');if(!el)return;el.textContent=storageMode==='local'?'Salvo':storageMode==='session'?'Só nesta sessão':storageMode==='memory'?'Sem backup':storageMode==='conflict'?'Conflito entre abas':'Carregando';el.title=storageNote||'Verificando armazenamento…';el.setAttribute('aria-label',storageNote||el.textContent);el.dataset.saveStatus=storageMode;el.classList.toggle('warn',storageMode!=='local');}
function restore(){
  pendingExternal=false;
  let payload=null;
  // Escolhe a cópia mais recente; não prioriza um localStorage antigo sobre um sessionStorage atualizado.
  for(const loc of [()=>localStorage.getItem(STORE),()=>sessionStorage.getItem(STORE)]){
    try{const raw=loc();if(raw){const x=JSON.parse(raw);if(x&&x.schema===2&&(!payload||(x.savedAt||0)>(payload.savedAt||0)))payload=x}}catch(e){}
  }
  if(payload){state={...initial(),...payload,config:{...defaultCfg(),...(payload.config||{})},essay:{text:'',notes:'',...(payload.essay||{})},preferences:{examLarge:false,...(payload.preferences||{})}};
    if(state.exam&&!Array.isArray(state.exam.ids))state.exam=null;
    if(state.exam)state.exam.ids=state.exam.ids.filter(id=>BANK.has(id));
    if(!Array.isArray(state.history))state.history=[];
    // Migração v2/v3 sem descartar nada: provas concluídas e iniciadas também contam como vistas.
    state.seenIds=unique([...(Array.isArray(state.seenIds)?state.seenIds:[]),...state.history.flatMap(h=>Array.isArray(h.ids)?h.ids:[]),...(state.exam?.ids||[])]).filter(id=>typeof id==='string');
  }
  try{const old=JSON.parse(localStorage.getItem(OLD)||'null');if(old?.exam?.ids?.length)legacyAvailable=old}catch(e){}
  document.documentElement.dataset.theme=state.theme==='dark'?'dark':'light';document.body.classList.toggle('exam-large',!!state.preferences?.examLarge);persist();
}
function go(page){
  if(state.exam&&page==='setup'){page='exam'};
  if(!$('#view-'+page))page='home';
  route=page;state.lastPage=page;document.body.classList.toggle('exam-active',page==='exam');document.body.classList.remove('exam-map-open');
  $$('.view').forEach(e=>e.classList.toggle('hidden',e.id!=='view-'+page));
  $$('.navitem, .mobile-nav [data-nav]').forEach(e=>{const active=e.dataset.nav===page||page==='writing'&&e.dataset.nav==='essay'||page==='exam'&&e.dataset.nav==='setup'||page==='result'&&e.dataset.nav==='history';e.classList.toggle('active',active);if(e.matches('.mobile-nav [data-nav]'))e.setAttribute('aria-current',active?'page':'false')});
  const pageNames={home:'Início',setup:'Simulados',exam:'Prova em andamento',result:'Correção',history:'Desempenho',planner:'Plano de estudos',essay:'Redação',data:'Backup e dados',profile:'Meu objetivo',explorer:'Provas e concursos',learn:'Professor',revisions:'Revisões',writing:'Redação / Temas e versões'};if($('#path-location'))$('#path-location').textContent='VYZO ACADEMY / '+(pageNames[page]||'Início');
  $('#side-nav').classList.remove('open');document.body.classList.remove('nav-is-open');$('#menu-btn').setAttribute('aria-expanded','false');$('#mobile-more')?.setAttribute('aria-expanded','false');
  const currentItem=$('#side-nav .navitem[data-nav="'+(page==='writing'?'essay':page)+'"]');if(currentItem?.closest('details'))currentItem.closest('details').open=true;
  const renders={home:renderHome,setup:renderSetup,exam:renderExam,result:renderResult,history:renderHistory,planner:renderPlanner,essay:renderEssay,data:renderData,profile:()=>window.ENEM_MENTOR?.render('profile'),explorer:()=>window.ENEM_MENTOR?.render('explorer'),learn:()=>window.ENEM_MENTOR?.render('learn'),revisions:()=>window.ENEM_MENTOR?.render('revisions'),writing:()=>window.ENEM_MENTOR?.render('writing')};
  if(renders[page])renders[page]();
  if(page==='result')window.ENEM_MENTOR?.decorateResult?.();
  persist();window.scrollTo({top:0,behavior:'instant'});
}
function notice(message,kind='warn'){$('#alert-slot').innerHTML=`<div class="notice ${kind}" role="status">${esc(message)}</div>`;setTimeout(()=>{const box=$('#alert-slot');if(box&&box.textContent===message)box.innerHTML=''},9000)}
let lastModalFocus=null;
function modal(title,text,buttons){lastModalFocus=document.activeElement;const root=$('#dialog-root');root.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${esc(title)}</h2><p>${esc(text)}</p><div class="btnrow" id="modal-actions"></div></div>`;
  const slot=root.querySelector('#modal-actions');buttons.forEach(({label,action,style='secondary'})=>{let b=document.createElement('button');b.type='button';b.className='button '+style;b.textContent=label;b.addEventListener('click',()=>{root.classList.add('hidden');root.innerHTML='';lastModalFocus?.focus?.();action?.()});slot.append(b)});
  root.classList.remove('hidden');slot.querySelector('button')?.focus();}
function allNew(){return validQuestions}
function availableFor(cfg){
  let pool=allNew();
  if(['day1','day2'].includes(cfg.mode))pool=pool.filter(q=>cfg.mode==='day1'?['Linguagens','Humanas'].includes(q.area):['Natureza','Matemática'].includes(q.area));
  else if(cfg.mode==='area')pool=pool.filter(q=>q.area===cfg.area);
  else if(cfg.mode==='subject')pool=pool.filter(q=>q.subject===cfg.subject);
  else if(cfg.mode==='topic')pool=pool.filter(q=>q.topic===cfg.topic);
  else if(cfg.mode==='targeted')pool=pool.filter(q=>cfg.ids?.includes(q.id));
  else if(cfg.mode==='errors'){
     const wrongIds=new Set(state.history.flatMap(h=>h.rows||[]).filter(r=>r.status==='wrong').map(r=>r.id));
     const topics=new Set([...wrongIds].map(id=>BANK.get(id)?.topic));
     pool=pool.filter(q=>wrongIds.has(q.id)||topics.has(q.topic));
  }
  pool=pool.filter(q=>!['Inglês','Espanhol'].includes(q.subject)||q.subject===cfg.language);
  return pool;
}
function interleave(items){let output=[],buckets=AREAS.map(a=>items.filter(q=>q.area===a));while(buckets.some(b=>b.length)){for(const b of buckets)if(b.length)output.push(b.shift())}return output}
function shuffled(items){let a=[...items];for(let i=a.length-1;i>0;i--){let k=Math.floor(Math.random()*(i+1));[a[i],a[k]]=[a[k],a[i]];}return a}
function seenSet(){return new Set([...(state.seenIds||[]),...state.history.flatMap(h=>h.ids||[]),...(state.exam?.ids||[])])}
function unseenFor(cfg){const seen=seenSet();return availableFor(cfg).filter(q=>!seen.has(q.id))}
function selection(cfg){const pool=unseenFor(cfg);return (['diagnostic','day1','day2'].includes(cfg.mode)?interleave(shuffled(pool)):shuffled(pool)).slice(0,cfg.count)}
function examDisplayLabel(cfg){return ({diagnostic:'Diagnóstico inicial',day1:'Primeiro dia — amostra',day2:'Segundo dia — amostra',area:cfg.area,subject:cfg.subject,topic:cfg.topic,errors:'Revisão dos erros',targeted:'Reteste com questões inéditas'})[cfg.mode]||'Simulado'}
function startExam(allowShort=false,confirmedSession=false){
 if(state.exam){go('exam');return}
 const cfg=state.config,remaining=unseenFor(cfg),n=Number(cfg.count),valid=allowShort?Number.isInteger(n)&&n>=1&&n<=100:COUNTS.includes(n);
 if(!valid){notice('Escolha 10, 20, 30... até 100 questões.','bad');return}
 if(remaining.length<n){notice('Não há '+n+' questões inéditas com estes filtros: restam '+remaining.length+'. Altere os filtros ou escolha uma quantidade permitida; não vamos repetir perguntas.','warn');return}
 if(storageMode==='memory'||storageMode==='conflict'){notice('É necessário resolver o salvamento antes de começar a prova. Exporte seus dados e verifique o armazenamento.','bad');return}
 if(storageMode==='session'&&!confirmedSession){modal('Atenção ao salvamento', 'Este navegador está salvando apenas nesta sessão. Fechar a aba ou limpar os dados pode apagar as respostas. Baixe um backup durante a prova.', [{label:'Cancelar'},{label:'Continuar ciente do risco',style:'',action:()=>startExam(allowShort,true)}]);return}
 if(cfg.timed && (!Number.isFinite(Number(cfg.minutes)) || Number(cfg.minutes)<1 || Number(cfg.minutes)>360)){notice('Escolha uma duração de 1 a 360 minutos para a contagem regressiva.','bad');return}
 const arr=selection(cfg),prior=[...(state.seenIds||[])];
 mapFilter='all';announcedTimes=new Set();state.exam={id:'exam-'+Date.now(),ids:arr.map(q=>q.id),answers:{},flagged:[],pos:0,startedAt:Date.now(),mode:cfg.mode,label:examDisplayLabel(cfg),timed:cfg.timed,limitSecs:cfg.timed?cfg.minutes*60:0,language:cfg.language,origin:'new',finished:false};
 // Reserva imediata: mesmo uma prova interrompida não reaparece como inédita.
 state.seenIds=unique([...prior,...state.exam.ids]);
 if(!persist()){state.exam=null;state.seenIds=prior;notice('Falha ao salvar o início da prova. Nenhuma questão foi consumida.','bad');return}
 go('exam');
}
function elapsed(ex){return Math.max(0,Math.floor((Date.now()-ex.startedAt)/1000))}
function remaining(ex){return ex.limitSecs-elapsed(ex)}
function calc(ex){const rows=ex.ids.map(id=>{let q=BANK.get(id),chosen=ex.answers[id];return {id,chosen:Number.isInteger(chosen)?chosen:null,status:!Number.isInteger(chosen)?'blank':chosen===q.answer?'correct':'wrong',area:q.area,subject:q.subject,topic:q.topic}});let answered=rows.filter(r=>r.status!=='blank').length,correct=rows.filter(r=>r.status==='correct').length;return {rows,answered,correct,blank:rows.length-answered,wrong:answered-correct,percent:answered?Math.round(correct/answered*100):0,coverage:Math.round(answered/rows.length*100)};}
function finishPrompt(){if(!state.exam)return;if(state.exam.timed&&remaining(state.exam)<=0){finishExam('tempo encerrado');return}const ex=state.exam,blanks=calc(ex).blank;modal('Finalizar e corrigir o simulado?',`Você tem ${blanks} questão(ões) em branco. Elas serão registradas como não respondidas e não entrarão no percentual. Você poderá consultar as respostas no histórico.`,[
 {label:'Voltar à prova',action:()=>go('exam')},{label:'Finalizar e corrigir',style:'',action:()=>finishExam('manual')}])}
function finishExam(reason='manual'){
 const ex=state.exam;if(!ex||ex.finished)return;if(ex.timed&&remaining(ex)<=0)reason='tempo encerrado';
 clearInterval(ticker);ticker=null;const dialog=$('#dialog-root');if(dialog){dialog.classList.add('hidden');dialog.innerHTML=''}lastModalFocus=null;
 const metrics=calc(ex);
 // Ponto adicional de recuperação gerado ANTES de limpar a prova; não remove backups anteriores.
 try { localStorage.setItem('enem-intelligence-recovery-'+ex.id,JSON.stringify({...state,recoveryAt:Date.now()})); }catch(e){}
 const result={id:ex.id,createdAt:Date.now(),startedAt:ex.startedAt,durationSecs:ex.timed&&reason==='tempo encerrado'?Math.min(elapsed(ex),ex.limitSecs):elapsed(ex),timeMode:ex.timed?'countdown':'elapsed',timeLimitSecs:ex.timed?ex.limitSecs:null,label:ex.label,mode:ex.mode,origin:ex.origin||'new',ids:ex.ids.slice(),answers:{...ex.answers},rows:metrics.rows,answered:metrics.answered,correct:metrics.correct,blank:metrics.blank,wrong:metrics.wrong,percent:metrics.percent,coverage:metrics.coverage,reason};
 // Atomic in-memory transition followed by persistence. Never discard results in a premature navigation.
 state.history=[result,...state.history.filter(x=>x.id!==result.id)];state.exam=null;state.lastResultId=result.id;const saved=persist();if(!saved)exportBackup();go('result');if(!saved)notice('A prova foi corrigida, mas não pôde ser salva neste navegador. Um backup foi baixado automaticamente.','warn');
}
function questionInfo(q){return q.origin==='Arquivo de recuperação (questão antiga)'?'Questão do banco anterior — recuperação':'Questão autoral • Contextualizada'}
function renderHome(){
 const m=state.mentor||{}, p=m.profile||{}, recent=state.history[0], used=state.history.reduce((n,h)=>n+(h.answered||0),0), free=unseenFor({...defaultCfg(),mode:'diagnostic'}).length;
 const profileDone=!!p.done, exam=state.exam, activePlan=m.plan?.lessons||[], nextStudy=activePlan.find(t=>!t.done), nextDue=Object.entries(m.revisions||{}).filter(([,r])=>Number(r.due)<=Date.now()).length;
 const totalAnswer=state.history.reduce((n,h)=>n+(h.answered||0),0),totalCorrect=state.history.reduce((n,h)=>n+(h.correct||0),0), pct=totalAnswer?Math.round(100*totalCorrect/totalAnswer):null;
 let days='';if(p.date){const diff=Math.ceil((new Date(p.date+'T12:00:00')-new Date())/86400000);if(Number.isFinite(diff))days=diff>=0?diff+' dia(s) para sua prova':'Data da prova já passou — atualize seu objetivo';}
 const weak=unique(state.history.flatMap(h=>(h.rows||[]).filter(r=>r.status==='wrong').map(r=>r.topic))).slice(0,4);
 $('#view-home').innerHTML=`
 <div class="dashboard-heading"><div><p class="eyebrow">VYZO ACADEMY</p><h1 class="page-title">Seu espaço de aprendizagem</h1><p class="lead">Continue de onde parou e concentre seus estudos no próximo passo.</p></div><button class="button secondary" data-act="backup">Fazer backup <span aria-hidden="true">↧</span></button></div>
 <section class="hero dashboard-hero"><div><div class="eyebrow">${profileDone?esc(p.exam||p.type||'Meu objetivo'):'Comece pelo seu objetivo'}</div><h2>${exam?'Seu simulado está salvo. Continue com segurança.':nextStudy?'Próxima atividade: '+esc(nextStudy.topic):profileDone?'Pronto para o próximo estudo.':'O seu caminho começa aqui.'}</h2><p>${exam?'Você marcou '+Object.values(exam.answers||{}).filter(Number.isInteger).length+' de '+exam.ids.length+' questões. Nenhuma resposta será descartada ao sair desta tela.':nextStudy?'Abra o professor, estude o assunto e depois pratique com novas questões.':profileDone?'Faça um diagnóstico para encontrar os conteúdos que merecem atenção.':'Defina sua prova e disponibilidade. Ou comece um simulado imediatamente.'}</p><div class="btnrow"><button class="button hero-primary" data-${exam?'act="resume"':nextStudy?'nav="learn"':'nav="profile"'}>${exam?'Retomar simulado':nextStudy?'Continuar estudando':profileDone?'Revisar meu objetivo':'Definir meu objetivo'} →</button><button class="button hero-secondary" data-nav="setup">${exam?'Ver meu simulado':'Criar simulado'}</button></div>${days?'<div class="hero-meta">'+esc(days)+'</div>':''}</div><div class="hero-art" aria-hidden="true"><span>✦</span><small>APRENDER · PRATICAR · EVOLUIR</small></div></section>
 ${pendingExternal?'<div class="notice warn"><strong>Dados alterados em outra aba.</strong> Exporte uma cópia antes de recarregar. <div class="btnrow"><button class="button secondary" data-act="backup">Baixar cópia</button><button class="button" data-act="sync-tab">Carregar versão mais recente</button></div></div>':''}
 <div class="grid cols3 metrics-grid"><article class="card metric-card"><span class="section-kicker">Simulados concluídos</span><div class="kpi">${state.history.length}</div><p class="small muted">Seu histórico continua disponível.</p></article><article class="card metric-card"><span class="section-kicker">Desempenho registrado</span><div class="kpi">${pct===null?'—':pct+'%'}</div><p class="small muted">${used} questões respondidas · não é nota TRI</p></article><article class="card metric-card"><span class="section-kicker">Questões inéditas</span><div class="kpi">${free}</div><p class="small muted">De ${validQuestions.length} autorais disponíveis, com sua língua escolhida.</p></article></div>
 <div class="grid cols2 home-lower"><article class="card"><div class="card-head"><div><span class="section-kicker">Seu estudo</span><h2>Próximos passos</h2></div><button class="button ghost" data-nav="planner">Ver plano →</button></div><div class="task-line"><span class="task-icon">01</span><div><strong>${nextStudy?esc(nextStudy.topic):'Organize sua rotina'}</strong><p class="small muted">${nextStudy?'Atividade pendente do plano personalizado':'Defina seus dias e minutos disponíveis'}</p></div><button class="button secondary" data-nav="${nextStudy?'learn':'profile'}">Abrir</button></div><div class="task-line"><span class="task-icon">02</span><div><strong>${nextDue?nextDue+' revisão(ões) para hoje':'Revisar conteúdo'}</strong><p class="small muted">Flashcards e exercícios de fixação</p></div><button class="button secondary" data-nav="revisions">Revisar</button></div><div class="task-line"><span class="task-icon">03</span><div><strong>Praticar com questões inéditas</strong><p class="small muted">Escolha 10 a 100 questões e seu tempo</p></div><button class="button secondary" data-nav="setup">Praticar</button></div></article>
 <article class="card"><div class="card-head"><div><span class="section-kicker">Diagnóstico</span><h2>Onde concentrar energia?</h2></div><button class="button ghost" data-nav="history">Resultados →</button></div>${weak.length?'<p class="muted">Assuntos com erros registrados (não representam diagnóstico definitivo):</p><div class="taglist">'+weak.map(t=>'<span class="chip">'+esc(t)+'</span>').join('')+'</div><p class="small muted">Estude os conceitos e faça retestes com perguntas novas.</p>':'<div class="empty compact-empty">Seus próximos simulados mostrarão quais assuntos você deve priorizar.</div>'}<div class="btnrow"><button class="button secondary" data-nav="learn">Abrir professor</button><button class="button ghost" data-nav="writing">Praticar redação</button></div></article></div>
 ${legacyAvailable&&!exam?'<div class="notice warn"><strong>Gabarito antigo encontrado.</strong> <button class="button secondary" data-act="recover-legacy">Recuperar prova anterior</button></div>':''}`;
}
function renderSetup(){
 const c=state.config, subjects=unique(NEW.map(q=>q.subject)).map(x=>`<option value="${esc(x)}" ${c.subject===x?'selected':''}>${esc(x)}</option>`).join(''), topics=unique(NEW.map(q=>q.topic)).map(x=>`<option value="${esc(x)}" ${c.topic===x?'selected':''}>${esc(x)}</option>`).join('');
 $('#view-setup').innerHTML=`<p class="eyebrow">Simulados · Configuração</p><h1 class="page-title">Monte sua prova</h1><p class="lead">Escolha o conteúdo, a quantidade e como deseja controlar o tempo. O gabarito aparece só depois de finalizar.</p>
 <div class="setup-layout"><div class="setup-main">
 <section class="card setup-card"><div class="setup-heading"><span class="step-number">01</span><div><h2>O que você quer praticar?</h2><p class="small muted">Escolha uma área, disciplina, assunto ou uma amostra geral.</p></div></div><div class="field"><label for="cfg-mode">Tipo de simulado</label><select id="cfg-mode"><option value="diagnostic" ${c.mode==='diagnostic'?'selected':''}>Diagnóstico — quatro áreas</option><option value="day1" ${c.mode==='day1'?'selected':''}>ENEM: primeiro domingo (amostra)</option><option value="day2" ${c.mode==='day2'?'selected':''}>ENEM: segundo domingo (amostra)</option><option value="area" ${c.mode==='area'?'selected':''}>Escolher uma área</option><option value="subject" ${c.mode==='subject'?'selected':''}>Escolher disciplina</option><option value="topic" ${c.mode==='topic'?'selected':''}>Escolher assunto</option><option value="errors" ${c.mode==='errors'?'selected':''}>Revisão direcionada aos erros</option></select></div><div class="grid cols2"><div class="field" id="area-field"><label for="cfg-area">Área</label><select id="cfg-area">${['Todas',...AREAS].map(x=>`<option value="${x}" ${c.area===x?'selected':''}>${esc(x==='Todas'?x:areaNames[x])}</option>`).join('')}</select></div><div class="field" id="subject-field"><label for="cfg-subject">Disciplina</label><select id="cfg-subject"><option>Todas</option>${subjects}</select></div><div class="field" id="topic-field"><label for="cfg-topic">Assunto</label><select id="cfg-topic"><option>Todos</option>${topics}</select></div><div class="field"><label for="cfg-language">Língua estrangeira</label><select id="cfg-language"><option ${c.language==='Inglês'?'selected':''}>Inglês</option><option ${c.language==='Espanhol'?'selected':''}>Espanhol</option></select></div></div></section>
 <section class="card setup-card"><div class="setup-heading"><span class="step-number">02</span><div><h2>Quantas questões?</h2><p class="small muted">De 10 em 10, até 100 — nunca acima do saldo de inéditas.</p></div></div><div class="field"><label for="cfg-count">Quantidade</label><select id="cfg-count" aria-describedby="count-hint">${COUNTS.map(n=>`<option value="${n}" ${n===c.count?'selected':''}>${n} questões</option>`).join('')}</select><span class="small muted" id="count-hint" role="status"></span></div></section>
 <section class="card setup-card"><div class="setup-heading"><span class="step-number">03</span><div><h2>Como controlar o tempo?</h2><p class="small muted">Escolha livremente entre medir seu tempo ou ter um prazo.</p></div></div><div class="field"><label for="cfg-time-mode">Modo de tempo</label><select id="cfg-time-mode" aria-describedby="time-mode-help"><option value="elapsed" ${!c.timed?'selected':''}>Crescente — apenas medir meu tempo</option><option value="countdown" ${c.timed?'selected':''}>Regressivo — terminar ao chegar a zero</option></select><p id="time-mode-help" class="small muted"></p></div><div class="field ${c.timed?'':'hidden'}" id="cfg-time-limit"><label for="cfg-minutes">Duração da prova (minutos)</label><input class="input" type="number" id="cfg-minutes" min="1" max="360" step="1" value="${c.minutes}" ${c.timed?'':'disabled'}><p class="small muted">Prazo de 1 a 360 minutos. A prova termina automaticamente ao esgotar.</p></div></section></div>
 <aside class="setup-aside"><div class="card setup-summary"><span class="section-kicker">RESUMO DA SUA PROVA</span><h2>Pronto para começar?</h2><dl class="summary-list"><div><dt>Conteúdo</dt><dd id="sum-content"></dd></div><div><dt>Questões</dt><dd id="sum-count"></dd></div><div><dt>Tempo</dt><dd id="sum-time"></dd></div></dl><div class="notice" style="margin-bottom:0"><strong>Não respondidas:</strong> ficam em branco, sem serem contadas como erro.</div><button class="button start-big" id="start-exam-btn" data-act="start">Iniciar meu simulado →</button><p class="tiny muted">Respostas salvas a cada marcação. Baixe também um backup JSON se desejar.</p><button class="button secondary backup-soft" data-act="backup">Baixar backup agora</button></div></aside></div>`;
 setupVisibility();
}
function setupVisibility(){
 const c=state.config;
 $('#area-field').classList.toggle('hidden',c.mode!=='area');$('#subject-field').classList.toggle('hidden',c.mode!=='subject');$('#topic-field').classList.toggle('hidden',c.mode!=='topic');
 if($('#cfg-minutes'))$('#cfg-minutes').disabled=!c.timed;
 if($('#cfg-time-limit'))$('#cfg-time-limit').classList.toggle('hidden',!c.timed);
 if($('#time-mode-help'))$('#time-mode-help').textContent=c.timed?'A prova será finalizada e corrigida automaticamente quando o tempo chegar a zero. Questões sem resposta ficarão em branco.':'O cronômetro contará do zero até você finalizar. Não existe limite de tempo nem encerramento automático.';
 const total=availableFor(c).length,remaining=unseenFor(c).length,options=COUNTS.filter(n=>n<=remaining),select=$('#cfg-count');
 const preferred=options.includes(Number(c.count))?Number(c.count):options.length?options[options.length-1]:10;
 c.count=preferred;
 select.innerHTML=COUNTS.map(n=>`<option value="${n}" ${n>remaining?'disabled':''}>${n} questões${n>remaining?' · indisponível':''}</option>`).join('');
 select.value=String(preferred);select.disabled=remaining<10;
 $('#start-exam-btn').disabled=remaining<10;
 $('#count-hint').textContent=`${remaining} inéditas de ${total} compatíveis. ${total-remaining} já usadas. ${remaining<10?'Não há perguntas suficientes para iniciar.':'As opções acima do saldo ficam bloqueadas.'}`;
 const m=({diagnostic:'Diagnóstico geral',day1:'ENEM: primeiro domingo',day2:'ENEM: segundo domingo',area:c.area,subject:c.subject,topic:c.topic,errors:'Revisar assuntos errados'});
 if($('#sum-content'))$('#sum-content').textContent=m[c.mode]||'Simulado';if($('#sum-count'))$('#sum-count').textContent=c.count+' questões';if($('#sum-time'))$('#sum-time').textContent=c.timed?'Regressivo · '+c.minutes+' min':'Crescente · sem limite';
 persist();
}
function renderFigure(visual){if(!visual)return'';
 const title=esc(visual.title||'Ilustração didática');let inner='';
 if(['bar','grouped','line'].includes(visual.type)){
   const series=visual.type==='grouped'?visual.series.map(s=>s.values):[visual.values];const max=Math.max(...series.flat(),1)*1.13;
   let grid='';for(let i=0;i<=4;i++){let y=220-i*46;grid+=`<line x1="56" y1="${y}" x2="595" y2="${y}" stroke="#d6e0eb"/><text x="48" y="${y+4}" text-anchor="end" font-size="12" fill="#64748b">${Math.round(max*i/4)}</text>`}
   let chart=grid+`<line x1="56" y1="220" x2="595" y2="220" stroke="#8295ac"/>`;
   const step=525/visual.labels.length;
   visual.labels.forEach((label,i)=>{
     const center=65+(i+.5)*step;chart+=`<text x="${center}" y="244" text-anchor="middle" font-size="13" fill="#52677e">${esc(label)}</text>`;
     if(visual.type==='bar') {let h=184*visual.values[i]/max;chart+=`<rect x="${center-21}" y="${220-h}" width="42" height="${h}" fill="#386fe9" rx="4"/><text x="${center}" y="${211-h}" font-size="12" fill="#213d69" text-anchor="middle">${visual.values[i]}</text>`}
     if(visual.type==='grouped'){let colors=['#386fe9','#ec9b41'];visual.series.forEach((s,k)=>{let h=184*s.values[i]/max;chart+=`<rect x="${center-20+k*21}" y="${220-h}" width="20" height="${h}" fill="${colors[k]}" rx="2"/><text x="${center-10+k*21}" y="${211-h}" font-size="11" fill="#213d69" text-anchor="middle">${s.values[i]}</text>`})}
   });
   if(visual.type==='line'){
     let pairs=visual.values.map((v,i)=>[65+(i+.5)*step,220-184*v/max]);chart+=`<polyline points="${pairs.map(p=>p.join(',')).join(' ')}" stroke="#386fe9" stroke-width="4" fill="none"/>`;pairs.forEach((p,i)=>{chart+=`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="#ed9b43"/><text x="${p[0]}" y="${p[1]-12}" font-size="12" fill="#213d69" text-anchor="middle">${visual.values[i]}</text>`})
   }
   if(visual.type==='grouped')chart+=`<rect x="190" y="266" width="14" height="10" fill="#386fe9"/><text x="210" y="275" font-size="12" fill="#52677e">Ano inicial</text><rect x="320" y="266" width="14" height="10" fill="#ec9b41"/><text x="340" y="275" font-size="12" fill="#52677e">Ano final</text>`;
   inner=`<svg viewBox="0 0 650 293" role="img" aria-label="${title}"><rect width="650" height="293" fill="#f8fbff" rx="10"/>${chart}</svg><details class="figure-data"><summary>Ver dados do gráfico em tabela</summary><table><thead><tr><th>Categoria</th>${visual.type==='grouped'?visual.series.map((s,i)=>`<th>${esc(s.name||s.label||'Série '+(i+1))}</th>`).join(''):'<th>Valor</th>'}</tr></thead><tbody>${visual.labels.map((label,i)=>`<tr><th>${esc(label)}</th>${(visual.type==='grouped'?visual.series.map(v=>v.values[i]):[visual.values[i]]).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
 }
 else if(visual.type==='table')inner=`<table aria-label="${title}"><thead><tr>${visual.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${visual.rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
 else if(visual.type==='rectangle')inner=`<svg viewBox="0 0 550 260" role="img" aria-label="Retângulo de 8 metros por 5 metros"><rect x="125" y="40" width="300" height="155" fill="#d4f1e2" stroke="#25785e" stroke-width="3"/><text x="275" y="223" text-anchor="middle" font-size="20" fill="#23425e">${esc(visual.w)}</text><text x="100" y="119" text-anchor="middle" font-size="20" fill="#23425e">${esc(visual.h)}</text></svg>`;
 else if(visual.type==='triangle')inner=`<svg viewBox="0 0 550 250" role="img" aria-label="Triângulo retângulo da escada"><polyline points="145,195 145,40 350,195 145,195" fill="#e8f3ff" stroke="#2457ad" stroke-width="4"/><rect x="145" y="176" width="20" height="19" fill="none" stroke="#2457ad" stroke-width="2"/><text x="240" y="220" text-anchor="middle" font-size="19" fill="#23425e">${esc(visual.a)}</text><text x="285" y="95" font-size="20" fill="#23425e">${esc(visual.c)}</text><text x="100" y="120" font-size="19" fill="#23425e">h</text></svg>`;
 else if(visual.type==='chain')inner=`<svg viewBox="0 0 650 165" role="img" aria-label="Cadeia alimentar: plantas para gafanhotos para sapos para cobras">${visual.labels.map((l,i)=>`<rect x="${13+i*161}" y="42" width="136" height="75" rx="13" fill="${i?'#ebf2ff':'#e2f3e8'}" stroke="#7798b5"/><text x="${81+i*161}" y="86" fill="#223b55" font-size="17" text-anchor="middle">${esc(l)}</text>${i<3?`<path d="M ${150+i*161} 80 l 18 0 m -7 -7 l 7 7 -7 7" stroke="#2d65c7" fill="none" stroke-width="3"/>`:''}`).join('')}</svg>`;
 else if(visual.type==='punnett')inner=`<svg viewBox="0 0 500 280" role="img" aria-label="Quadro de Punnett com cruzamento Aa por Aa"><g fill="#e7f0ff" stroke="#7d99c8">${[0,1].map(i=>[0,1].map(j=>`<rect x="${145+i*110}" y="${55+j*96}" width="105" height="90"/>`).join('')).join('')}</g>${['AA','Aa','Aa','aa'].map((x,i)=>`<text x="${197+i%2*110}" y="${109+Math.floor(i/2)*96}" font-size="27" text-anchor="middle" fill="#253b65">${x}</text>`).join('')}<text x="195" y="39" font-size="22" fill="#253b65">A</text><text x="302" y="39" font-size="22" fill="#253b65">a</text><text x="114" y="111" font-size="22" fill="#253b65">A</text><text x="114" y="209" font-size="22" fill="#253b65">a</text></svg>`;
 else if(visual.type==='circuit')inner=`<svg viewBox="0 0 550 220" role="img" aria-label="Circuito: fonte de 12 volts e resistor de 6 ohms"><path d="M125 48H420V171H125V48" stroke="#274c79" fill="none" stroke-width="4"/><path d="M240 48v-17m23 17v-27" stroke="#274c79" stroke-width="5"/><rect x="392" y="90" width="56" height="40" fill="#eaf1ff" stroke="#274c79" stroke-width="3"/><text x="475" y="117" font-size="18" fill="#274c79">${esc(visual.resistance)}</text><text x="220" y="92" font-size="18" fill="#274c79">${esc(visual.voltage)}</text></svg>`;
 else if(visual.type==='poster')inner=`<svg viewBox="0 0 550 235" role="img" aria-label="Cartaz ilustrado com celular quebrado e símbolo de reciclagem"><rect width="550" height="235" rx="12" fill="#e3f2ec"/><rect x="54" y="38" width="97" height="160" rx="14" fill="#183d50"/><rect x="66" y="54" width="72" height="111" rx="6" fill="#f8fbff"/><path d="M66 127l32-33 18 24 22-39" fill="none" stroke="#7491a8" stroke-width="4"/><text x="197" y="105" font-size="66" fill="#087c61">♻</text><text x="190" y="155" font-size="22" fill="#234b49">DESCARTE CONSCIENTE</text><text x="190" y="184" font-size="16" fill="#234b49">Procure um ponto de coleta</text></svg>`;
 return `<figure class="figure">${inner}<figcaption>${title} • Ilustração original didática</figcaption></figure>`;
}
function renderStimulus(q){let txt=q.context??q.text??'';return `<div class="stimulus"><div class="section-kicker">Texto de apoio / situação-problema</div>${esc(txt)}<span class="source">${esc(q.source||'Questão autoral de revisão')}</span></div>${renderFigure(q.visual)}`}
function renderQuestion(q,i,chosen,corrected=false){return `<div class="q-heading"><span class="chip">Questão ${i+1}</span><span class="small muted">${esc(q.subject)} • ${esc(q.topic)}</span></div>${renderStimulus(q)}<p class="question-stem">${esc(q.stem||q.text)}</p><div class="choices">${q.options.map((op,k)=>`<label class="choice"><input type="radio" name="answer" value="${k}" data-choice="${k}" ${chosen===k?'checked':''} ${corrected?'disabled':''}><span class="choice-letter">${A[k]})</span><span>${esc(op)}</span></label>`).join('')}</div>`}
function renderExam(){let ex=state.exam;if(!ex){go('home');return}if(ex.timed&&remaining(ex)<=0){finishExam('tempo encerrado');return}let metrics=calc(ex),q=BANK.get(ex.ids[ex.pos]);if(!q){notice('Questão ausente na base. Exporte um backup antes de continuar.','bad');return}
 const mapItems=ex.ids.map((id,i)=>({id,i})).filter(({id})=>mapFilter==='all'||(mapFilter==='answered'&&Number.isInteger(ex.answers[id]))||(mapFilter==='blank'&&!Number.isInteger(ex.answers[id]))||(mapFilter==='flagged'&&ex.flagged.includes(id)));
 const mapButtons=mapItems.map(({id,i})=>`<button class="q-dot ${Number.isInteger(ex.answers[id])?'done':''} ${ex.flagged.includes(id)?'flagged':''} ${i===ex.pos?'current':''}" data-position="${i}" aria-label="Ir para questão ${i+1}">${i+1}</button>`).join('');
 $('#view-exam').innerHTML=`<div id="timer-notice" class="sr-only" role="status" aria-live="polite"></div><div class="exam-top"><div class="exam-head"><div><div class="eyebrow">${esc(ex.label)} · ${ex.ids.length} questões</div><h2>Questão ${ex.pos+1} de ${ex.ids.length}</h2></div><div class="taglist"><span class="chip" id="exam-timer" role="timer" aria-label="Tempo do simulado">${ex.timed?'Tempo restante: '+fmtTime(remaining(ex)):'Tempo decorrido: '+fmtTime(elapsed(ex))}</span><span class="chip">${metrics.answered}/${ex.ids.length} respondidas</span></div></div><div class="progress-track"><div class="progress-fill" style="width:${metrics.coverage}%"></div></div></div>
 <div class="exam-toolbar"><button class="button secondary" data-act="toggle-map" aria-controls="exam-map-panel" aria-expanded="false">☷ Mapa de questões</button><button class="button ghost" data-act="font-toggle" aria-label="Aumentar ou diminuir a fonte">A+ Tamanho do texto</button><button class="button secondary" data-act="backup" aria-label="Baixar backup desta prova">↓ Backup</button><button class="button ghost" data-nav="home">Salvar e sair</button></div><div class="exam-shell"><div><article class="card exam-question">${renderQuestion(q,ex.pos,ex.answers[q.id])}<div class="btnrow"><button class="button secondary" data-act="clear-choice">Deixar em branco</button><button class="button ghost" data-act="flag">${ex.flagged.includes(q.id)?'★ Retirar marcação':'☆ Marcar para revisar'}</button></div></article><div class="btnrow exam-actions"><button class="button secondary" data-act="prev" ${ex.pos===0?'disabled':''}>← Anterior</button><button class="button secondary" data-act="next" ${ex.pos===ex.ids.length-1?'disabled':''}>Próxima →</button><button class="button secondary" data-act="jump-pending" ${metrics.blank===0?'disabled':''}>Ir para pendente</button><button class="button" data-act="finish">Finalizar a prova</button></div></div>
 <aside class="q-sidebar stack" id="exam-map-panel" aria-label="Mapa de questões"><div class="card"><button class="button ghost drawer-close" data-act="toggle-map">✕ Fechar mapa</button><div class="section-kicker">Mapa de questões</div><p class="small muted">Clique no número para navegar. Verde = respondida. Borda amarela = revisar.</p><div class="q-tools"><label for="q-jump-number" class="small">Ir à questão</label><input id="q-jump-number" type="number" min="1" max="${ex.ids.length}" value="${ex.pos+1}" class="input" aria-label="Ir para número da questão"><button class="button secondary" data-act="jump-number">Ir</button></div><div class="map-filters" role="group" aria-label="Filtrar questões">${[['all','Todas'],['answered','Respondidas'],['blank','Pendentes'],['flagged','Marcadas']].map(([key,label])=>`<button type="button" class="button ${mapFilter===key?'':'secondary'}" aria-pressed="${mapFilter===key}" data-map-filter="${key}">${label}</button>`).join('')}</div><div class="q-grid">${mapButtons||'<p class="small muted">Nenhuma questão neste filtro.</p>'}</div><div class="divider"></div><p class="small"><strong>${metrics.answered}</strong> respondidas · <strong>${metrics.blank}</strong> pendentes · <strong>${ex.flagged.length}</strong> marcadas</p></div><div class="card"><h3>Suas respostas estão protegidas</h3><p class="small muted">Salvamento automático por alternativa. Faça um arquivo de segurança a qualquer momento.</p><button class="button secondary" data-act="backup">Baixar backup (.json)</button><p class="small muted">${esc(storageNote)}</p></div></aside></div><div class="map-shade" data-act="toggle-map" aria-hidden="true"></div>`;
 clearInterval(ticker);ticker=setInterval(()=>{const now=$('#exam-timer');if(!state.exam||!now){clearInterval(ticker);return}let e=state.exam;now.textContent=e.timed?'Tempo restante: '+fmtTime(remaining(e)):'Tempo decorrido: '+fmtTime(elapsed(e));now.classList.toggle('timer-low',Boolean(e.timed&&remaining(e)<=300));if(e.timed){const seconds=remaining(e);for(const mark of [600,300,60]){if(seconds<=mark&&seconds>0&&!announcedTimes.has(mark)){announcedTimes.add(mark);const alert=$('#timer-notice');if(alert)alert.textContent='Atenção: restam '+Math.ceil(seconds/60)+' minutos para encerrar a prova.';break}}}if(e.timed&&remaining(e)<=0){clearInterval(ticker);finishExam('tempo encerrado')}},1000);
}
function pickAnswer(n){const ex=state.exam;if(!ex)return;if(ex.timed&&remaining(ex)<=0){finishExam('tempo encerrado');return}const id=ex.ids[ex.pos];if(!Number.isInteger(n)||n<0||n>4)return;ex.answers[id]=n;persist();renderExam();}
function moveQuestion(pos){const ex=state.exam;if(!ex)return;document.body.classList.remove('exam-map-open');if(ex.timed&&remaining(ex)<=0){finishExam('tempo encerrado');return}ex.pos=Math.max(0,Math.min(ex.ids.length-1,pos));persist();renderExam();window.scrollTo({top:0,behavior:'instant'});}
function renderResult(){let r=state.history.find(x=>x.id===state.lastResultId)||state.history[0];if(!r){$('#view-result').innerHTML='<div class="empty">Nenhum simulado corrigido.</div>';return}
 const byArea=AREAS.map(a=>{let x=r.rows.filter(z=>z.area===a),y=x.filter(z=>z.status!=='blank');return {area:a,total:x.length,responded:y.length,correct:y.filter(z=>z.status==='correct').length}}).filter(x=>x.total);
 const wrongTopics=unique(r.rows.filter(z=>z.status==='wrong').map(z=>z.topic));
 $('#view-result').innerHTML=`<p class="eyebrow">Correção finalizada</p><h1 class="page-title">${esc(r.label)}</h1><p class="lead">${fmtDate(r.createdAt)} • Duração: ${fmtTime(r.durationSecs)} • ${esc(r.reason==='tempo encerrado'?'Prazo encerrado':'Prova concluída')}</p>
 <div class="grid cols3"><div class="card"><div class="section-kicker">Acertos</div><div class="kpi status-good">${r.correct} / ${r.answered}</div><div class="muted small">Questões respondidas</div></div><div class="card"><div class="section-kicker">Aproveitamento</div><div class="kpi">${r.percent}%</div><div class="muted small">Apenas entre respondidas — não é TRI</div></div><div class="card"><div class="section-kicker">Cobertura</div><div class="kpi">${r.coverage}%</div><div class="muted small">${r.blank} em branco • ${r.wrong} erradas</div></div></div>
 <div class="grid cols2" style="margin-top:16px"><div class="card"><h2>Desempenho por área</h2>${byArea.map(x=>`<div class="small"><strong>${esc(x.area)}</strong> — ${x.correct}/${x.responded} respondidas<div class="statbar"><div style="width:${x.responded?100*x.correct/x.responded:0}%"></div></div></div>`).join('')}</div><div class="card"><h2>Prioridades de revisão</h2>${wrongTopics.length?`<p>Assuntos que você errou nesta amostra:</p><div class="taglist">${wrongTopics.map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div>`:'<p class="muted">Nenhum erro registrado nesta prova. Verifique a cobertura: poucas respostas ainda não demonstram domínio completo.</p>'}<div class="btnrow"><button class="button secondary" data-nav="planner">Montar revisão</button><button class="button secondary" data-act="backup">Exportar histórico</button></div></div></div>
 <h2 style="margin-top:28px">Gabarito e correção comentada</h2><p class="muted">Suas respostas aparecem lado a lado com as corretas; as explicações foram preparadas para este banco autoral.</p><div class="stack">${r.ids.map((id,i)=>{let q=BANK.get(id);if(!q)return `<div class="notice warn">Questão ${i+1} (${esc(id)}) não encontrada no banco atual; a resposta permanece no backup.</div>`;
 const row=r.rows.find(t=>t.id===id)||{chosen:null,status:'blank'},v=row.chosen,cls=row.status==='correct'?'correct':row.status==='wrong'?'wrong':'blank';return `<article class="card result-block"><div class="q-heading"><strong>Questão ${i+1} — ${esc(q.topic)}</strong><span class="pill ${row.status==='correct'?'status-good':row.status==='wrong'?'status-bad':'status-warn'}">${row.status==='correct'?'✓ Acertou':row.status==='wrong'?'✕ Errou':'Não respondida'}</span></div>${renderStimulus(q)}<p class="question-stem">${esc(q.stem||q.text)}</p><div class="answer-box ${cls}"><strong>Sua resposta:</strong> ${Number.isInteger(v)?esc(A[v]+') '+q.options[v]):'Não respondida'}<br><strong>Resposta correta:</strong> ${esc(A[q.answer]+') '+q.options[q.answer])}<p style="margin-bottom:0"><strong>Explicação:</strong> ${esc(q.explanation)}</p></div><div class="btnrow"><button type="button" class="button secondary" data-mentor="learn-topic" data-mentor-topic="${esc(q.topic)}">Estudar este assunto</button></div></article>`}).join('')}</div><div class="btnrow"><button class="button" data-nav="setup">Novo simulado</button><button class="button secondary" data-act="backup">Baixar resultado e respostas</button></div>`;
}
function renderHistory(){let h=state.history;$('#view-history').innerHTML=`<p class="eyebrow">Aprendizagem</p><h1 class="page-title">Meu desempenho</h1><p class="lead">Resultados baseados apenas em respostas registradas. Amostras pequenas exigem cautela.</p>${h.length?`<div class="grid cols3"><div class="card"><span class="section-kicker">Simulados</span><div class="kpi">${h.length}</div></div><div class="card"><span class="section-kicker">Questões respondidas</span><div class="kpi">${h.reduce((n,x)=>n+x.answered,0)}</div></div><div class="card"><span class="section-kicker">Aproveitamento agregado</span><div class="kpi">${Math.round(100*h.reduce((n,x)=>n+x.correct,0)/Math.max(1,h.reduce((n,x)=>n+x.answered,0)))}%</div></div></div><div class="card" style="margin-top:17px"><h2>Histórico de avaliações</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Tipo</th><th>Acertos</th><th>Cobertura</th><th></th></tr></thead><tbody>${h.map(x=>`<tr><td>${fmtDate(x.createdAt)}</td><td>${esc(x.label)}</td><td>${x.correct}/${x.answered} (${x.percent}%)</td><td>${x.coverage}%</td><td><button class="button secondary" data-result="${esc(x.id)}">Ver correção</button></td></tr>`).join('')}</tbody></table></div></div>`:'<div class="empty">Nenhuma prova concluída ainda. Faça um diagnóstico para começar a construir seu histórico.</div>'}`}
function computeNeeds(){let map=new Map();for(let h of state.history)for(let r of h.rows||[]){if(r.status==='blank')continue;let x=map.get(r.topic)||{topic:r.topic,subject:r.subject,area:r.area,total:0,correct:0};x.total++;if(r.status==='correct')x.correct++;map.set(r.topic,x)}return [...map.values()].map(x=>({...x,rate:x.correct/x.total})).sort((a,b)=>{let pa=a.total>=3?a.rate:0.55,pb=b.total>=3?b.rate:0.55;return pa-pb||b.total-a.total})}
function renderPlanner(){let topics=computeNeeds();let suggestions=topics.length?topics.slice(0,7):[
{topic:'Interpretação de textos',area:'Linguagens',total:0},{topic:'Porcentagem',area:'Matemática',total:0},{topic:'Ecologia e energia',area:'Natureza',total:0},{topic:'Urbanização e enchentes',area:'Humanas',total:0}];
 let plan=suggestions.map((s,i)=>({day:i+1,topic:s.topic,area:s.area,guide:s.total<3?'Poucas respostas: faça um teste antes de concluir que domina.':`${Math.round(s.rate*100)}% em ${s.total} questão(ões) do histórico.`}));
 $('#view-planner').innerHTML=`<p class="eyebrow">Revisão adaptativa</p><h1 class="page-title">Plano de estudos</h1><p class="lead">Distribuição sugerida com base nos erros do histórico; se não houver resultados, mostra prioridades gerais sem fingir um diagnóstico individual.</p><div class="notice">Rotina de 2 horas: <strong>25 min</strong> de conteúdo + <strong>20 min</strong> de exemplos + <strong>55 min</strong> de exercícios + <strong>20 min</strong> para corrigir e registrar erros.</div><div class="card"><h2>Roteiro recomendado</h2>${plan.map(p=>`<div class="plan-day"><div class="plan-num">${p.day}</div><div><strong>${esc(p.topic)}</strong> <span class="chip">${esc(p.area)}</span><p class="small muted" style="margin:4px 0">${esc(p.guide)}</p><p class="small" style="margin:4px 0">25 min teoria · 20 min exemplos · 55 min questões · 20 min correção</p></div></div>`).join('')}</div><div class="btnrow"><button class="button" data-nav="setup">Praticar assuntos</button><button class="button secondary" data-act="backup">Exportar progresso</button></div>`
 if(window.ENEM_MENTOR?.renderPlanBox)$('#view-planner').insertAdjacentHTML('afterbegin',window.ENEM_MENTOR.renderPlanBox());
}
function renderEssay(){const txt=state.essay.text||'',words=txt.trim()?txt.trim().split(/\s+/).length:0;$('#view-essay').innerHTML=`<p class="eyebrow">Produção textual</p><h1 class="page-title">Redação</h1><nav class="writing-tabs" aria-label="Modos de redação"><button class="writing-tab current" data-nav="essay">Rascunho rápido</button><button class="writing-tab" data-nav="writing">Temas e versões</button></nav><p class="lead">Escreva e salve um rascunho local. A plataforma oferece checklist e contagem de palavras, mas não atribui nota oficial nem correção por IA sem integração.</p><div class="grid cols2"><div class="card"><h2>Tema autoral de treino</h2><p><strong>Desafios para ampliar o acesso à leitura e às bibliotecas públicas no Brasil</strong></p><p class="muted">Construa uma dissertação-argumentativa em modalidade escrita formal, apresentando tese, argumentos e proposta de intervenção que respeite os direitos humanos.</p><p class="small">Checklist das cinco competências: domínio da escrita formal; compreensão do tema; seleção e organização dos argumentos; coesão; proposta de intervenção.</p></div><div class="card"><h2>Guia de estrutura</h2><p><strong>Introdução:</strong> contextualização + tese.</p><p><strong>Desenvolvimento 1 e 2:</strong> argumentos sustentados por explicações e exemplos.</p><p><strong>Conclusão:</strong> agente, ação, meio, finalidade e detalhamento.</p><p class="small muted">Critérios didáticos; nenhuma nota é produzida automaticamente.</p></div></div><div class="card" style="margin-top:17px"><label class="label" for="essay-text">Seu rascunho</label><p class="small muted" id="word-count">${words} palavras • salvo automaticamente</p><textarea id="essay-text" placeholder="Escreva sua introdução, desenvolvimento e conclusão…">${esc(txt)}</textarea><div class="field"><label for="essay-notes">Anotações sobre melhorias</label><textarea id="essay-notes" style="min-height:100px" placeholder="O que melhorar na próxima versão?">${esc(state.essay.notes||'')}</textarea></div><button class="button secondary" data-act="essay-export">Baixar redação (.txt)</button></div>`}
function renderData(){const oldCount=legacyAvailable?.exam?.ids?.length||0;$('#view-data').innerHTML=`<p class="eyebrow">Segurança e portabilidade</p><h1 class="page-title">Backup e recuperação</h1><p class="lead">Seus dados permanecem no navegador. Esta plataforma não possui conta, servidor de respostas nem sincronização automática entre dispositivos.</p><div class="grid cols2"><div class="card"><h2>Exportar tudo</h2><p>Baixe provas em andamento, respostas já marcadas, histórico e redação em um arquivo JSON. Faça isso durante a prova se precisar de uma cópia extra.</p><button class="button" data-act="backup">Baixar meu backup (.json)</button></div><div class="card"><h2>Importar backup</h2><p>Selecione um arquivo gerado pela plataforma ou pela ferramenta de recuperação. Escolha mesclar ou substituir; o sistema cria backup antes da operação.</p><input class="input" id="import-file" type="file" accept=".json,application/json"></div></div><div class="card" style="margin-top:16px"><h2>Recuperar versão antiga</h2><p>Uma prova antiga com as questões da v1 pode ser retomada se o mesmo navegador ainda conservar os dados na chave antiga. Esse processo <strong>não apaga</strong> os dados atuais.</p><p class="small muted">${oldCount?'Possível prova anterior encontrada com '+oldCount+' questões.':'Nenhuma prova antiga detectada neste navegador.'}</p><button class="button secondary" data-act="recover-legacy" ${oldCount?'':'disabled'}>Verificar e recuperar prova antiga</button></div><div class="notice warn" style="margin-top:16px"><strong>Não apague dados do site ou limpe o armazenamento do navegador sem exportar o backup.</strong> Em janela anônima ou com armazenamento bloqueado, as respostas podem não persistir após fechar a sessão.</div>`;renderRecoveryExtras()}
function renderRecoveryExtras(){
 const el=$('#view-data');if(!el)return;
 const exams=Array.isArray(state.savedExams)?state.savedExams:[],drafts=Array.isArray(state.essay?.importedDrafts)?state.essay.importedDrafts:[];
 el.insertAdjacentHTML('beforeend',`<section class="card mentor-slab"><h2>Dados preservados de importações</h2><p class="muted small">A importação pode combinar históricos sem apagar a prova que você já está respondendo.</p><p>${exams.length} prova(s) importada(s) em espera · ${drafts.length} rascunho(s) preservado(s).</p><div class="stack">${exams.slice(-4).map((item,i)=>`<button class="button secondary" data-act="recover-import-exam" data-exam-import="${exams.length-Math.min(4,exams.length)+i}">Recuperar prova: ${esc(item.exam?.label||'Simulado')} (${item.exam?.ids?.length||0} questões)</button>`).join('')}${drafts.slice(-5).map((d,i)=>`<button class="button secondary" data-act="recover-draft" data-draft-index="${drafts.length-Math.min(5,drafts.length)+i}">Restaurar rascunho importado ${i+1}</button>`).join('')}</div></section>`);
}
function exportBackup(){download('VYZO_ACADEMY_BACKUP_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({...state,exportedAt:Date.now(),app:'VYZO ACADEMY v1'},null,2),'application/json')}
function download(name,body,type){let url=URL.createObjectURL(new Blob([body],{type:type+';charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function validateHistoryRecord(record){
 if(!record||typeof record!=='object'||typeof record.id!=='string'||!record.id.trim()||!Array.isArray(record.ids)||!record.ids.length||record.ids.length>100||new Set(record.ids).size!==record.ids.length||record.ids.some(id=>typeof id!=='string'||!id))throw Error('Histórico contém uma prova sem identificadores válidos. Nenhum dado foi alterado.');
 const oldRows=Array.isArray(record.rows)?record.rows:[];
 const byId=new Map();
 for(const row of oldRows){if(!row||typeof row.id!=='string'||!record.ids.includes(row.id)||byId.has(row.id)||!['correct','wrong','blank'].includes(row.status)||!['number','object'].includes(typeof row.chosen))throw Error('Histórico com respostas inválidas na prova '+record.id);byId.set(row.id,row)}
 const answers=record.answers&&typeof record.answers==='object'&&!Array.isArray(record.answers)?record.answers:{};
 if(Object.entries(answers).some(([id,n])=>!record.ids.includes(id)||!Number.isInteger(n)||n<0||n>4))throw Error('O histórico contém alternativas fora do intervalo permitido.');
 // Não substituir respostas desconhecidas por brancos: preservar a origem, ou rejeitar com explicação.
 if(record.ids.some(id=>!byId.has(id)&&!Object.prototype.hasOwnProperty.call(answers,id)))throw Error('Histórico incompleto na prova '+record.id+': faltam dados das questões. Importe uma cópia integral.');
 const rows=record.ids.map(id=>{const saved=byId.get(id),q=BANK.get(id),chosen=Number.isInteger(answers[id])?answers[id]:Number.isInteger(saved?.chosen)?saved.chosen:null;
  const status=chosen===null?'blank':q?chosen===q.answer?'correct':'wrong':saved?.status;
  if(!['correct','wrong','blank'].includes(status))throw Error('Histórico não verificável: '+id);
  if(saved&&saved.status!==status)throw Error('Histórico com inconsistência de gabarito: '+id);
  return {id,chosen,status,area:q?.area||saved?.area||'Outros',subject:q?.subject||saved?.subject||'Não identificado',topic:q?.topic||saved?.topic||'Não identificado'};
 });
 const answered=rows.filter(r=>r.status!=='blank').length,correct=rows.filter(r=>r.status==='correct').length;
 const createdAt=Number(record.createdAt)||Date.now();
 return {...record,rows,answered,correct,wrong:answered-correct,blank:rows.length-answered,percent:answered?Math.round(correct/answered*100):0,coverage:Math.round(answered/rows.length*100),createdAt,label:String(record.label||'Prova importada').slice(0,120),durationSecs:Math.max(0,Number(record.durationSecs)||0)};
}
function validateImported(original){
 if(!original||typeof original!=='object'||Array.isArray(original))throw Error('Arquivo sem dados válidos.');
 // Validar em uma cópia para que um JSON incorreto nunca altere objetos existentes.
 const x=JSON.parse(JSON.stringify(original));
 if(x.schema!==undefined&&![1,2].includes(x.schema))throw Error('Versão de backup não reconhecida. Preserve o arquivo original.');
 if(x.history!==undefined&&!Array.isArray(x.history))throw Error('Histórico inválido no arquivo.');
 if((x.history||[]).length>10000)throw Error('O histórico excede o limite de importação segura.');
 x.history=(x.history||[]).map(validateHistoryRecord);
 if(new Set(x.history.map(r=>r.id)).size!==x.history.length)throw Error('Histórico contém identificadores repetidos.');
 if(x.exam){
  if(!Array.isArray(x.exam.ids)||x.exam.ids.length===0||x.exam.ids.length>100||!x.exam.ids.every(id=>typeof id==='string')||new Set(x.exam.ids).size!==x.exam.ids.length)throw Error('Identificadores inválidos.');
  if(x.exam.ids.some(id=>!BANK.has(id)))throw Error('Algumas questões não existem neste banco. Guarde o arquivo original.');
  if(!x.exam.answers||typeof x.exam.answers!=='object'||Array.isArray(x.exam.answers))x.exam.answers={};
  if(Object.entries(x.exam.answers).some(([id,v])=>!x.exam.ids.includes(id)||!Number.isInteger(v)||v<0||v>4))throw Error('Respostas fora do intervalo permitido.');
  if(!Number.isInteger(x.exam.pos))x.exam.pos=0;
  x.exam.pos=Math.max(0,Math.min(x.exam.pos,x.exam.ids.length-1));
  if(!Array.isArray(x.exam.flagged))x.exam.flagged=[];
  x.exam.flagged=x.exam.flagged.filter(id=>x.exam.ids.includes(id));
  if(!Number.isFinite(Number(x.exam.startedAt)))x.exam.startedAt=Date.now();
 }
 if(x.seenIds!==undefined&&(!Array.isArray(x.seenIds)||x.seenIds.some(id=>typeof id!=='string')))throw Error('Controle de questões já usadas inválido.');
 if(x.essay!==undefined&&(!x.essay||typeof x.essay!=='object'||(x.essay.text!==undefined&&typeof x.essay.text!=='string')))throw Error('Texto da redação inválido.');
 if(x.savedExams!==undefined&&!Array.isArray(x.savedExams))throw Error('Provas de recuperação inválidas.');
 if(x.mentor!==undefined&&(!x.mentor||typeof x.mentor!=='object'))throw Error('Dados de aprendizagem inválidos.');
 return x;
}
function applyImport(x,mode='merge'){
 x=validateImported(x);
 if(pendingExternal){notice('Outra aba atualizou seus dados. Baixe uma cópia e sincronize antes de importar.','bad');return}
 // Gera uma cópia ANTES de toda importação e guarda snapshot local, quando possível.
 exportBackup();
 try{localStorage.setItem('enem-intelligence-preimport-'+Date.now(),JSON.stringify(state))}catch(e){}
 let next;
 if(mode==='replace'){
   next={...initial(),...x,config:{...defaultCfg(),...(x.config||{})},essay:{text:'',notes:'',...(x.essay||{})},mentor:x.mentor||state.mentor};
   if(!Array.isArray(next.history))next.history=[];
 }else{
   const importedHist=Array.isArray(x.history)?x.history:[];
   const byId=new Map(state.history.filter(r=>r?.id).map(r=>[r.id,r]));for(const r of importedHist){if(r?.id&&!byId.has(r.id))byId.set(r.id,r)}
   const mergedEssay={...state.essay,importedDrafts:[...(state.essay?.importedDrafts||[])]};
   if(x.essay?.text && x.essay.text!==state.essay?.text){
     if(!state.essay?.text){mergedEssay.text=x.essay.text;mergedEssay.notes=x.essay.notes||''}
     else if(!mergedEssay.importedDrafts.some(d=>d.text===x.essay.text))mergedEssay.importedDrafts.push({text:x.essay.text,notes:x.essay.notes||'',importedAt:Date.now()});
   }
   const myMentor=state.mentor||{},fromMentor=x.mentor||{},myWriter=myMentor.writing||{},fromWriter=fromMentor.writing||{};
   const versions=[...(myWriter.history||[])];for(const v of (fromWriter.history||[]))if(!versions.some(a=>a.text===v.text && a.topic===v.topic && a.date===v.date))versions.push(v);
   if(fromWriter.text && fromWriter.text!==myWriter.text&&!versions.some(v=>v.text===fromWriter.text))versions.push({date:Date.now(),topic:fromWriter.topic||'Rascunho importado',text:fromWriter.text,notes:fromWriter.notes||'',words:fromWriter.text.trim().split(/\s+/).length});
   next={...state,history:[...byId.values()],essay:mergedEssay,
     mentor:{...fromMentor,...myMentor,writing:{...fromWriter,...myWriter,history:versions}},
     savedExams:[...(state.savedExams||[])]};
   if(x.exam?.ids?.length){if(state.exam){if(x.exam.id!==state.exam.id&&!next.savedExams.some(v=>v.exam?.id===x.exam.id))next.savedExams.push({exam:x.exam,importedAt:Date.now()})}else next.exam=x.exam}
 }
 next.seenIds=unique([...(state.seenIds||[]),...(Array.isArray(x.seenIds)?x.seenIds:[]),...(next.seenIds||[]),...next.history.flatMap(r=>r?.ids||[]),...(next.exam?.ids||[]),...(next.savedExams||[]).flatMap(v=>v.exam?.ids||[])]).filter(id=>typeof id==='string');
 const before=state;state=next;
 if(!persist()){state=before;notice('Não foi possível confirmar o salvamento. Seus dados em memória foram restaurados; preserve o backup baixado.','bad');return}
 notice(mode==='merge'?'Históricos combinados; a prova atual e os rascunhos foram preservados.':'Backup restaurado após criar cópia de segurança.','good');go(state.exam?'exam':'history');
}
function recoverLegacy(){if(!legacyAvailable?.exam){notice('Nenhuma prova antiga encontrada neste navegador.');return}let old=legacyAvailable;
 const ex=old.exam;if(ex.ids.some(id=>!BANK.has(id))){notice('O banco antigo não contém todas as questões identificadas. Exporte o armazenamento original e preserve-o.','bad');return}
 modal('Importar prova da versão anterior?',`Encontramos ${ex.ids.length} questões antigas. As respostas marcadas serão mantidas. Seus resultados atuais não serão excluídos, mas uma prova v2 em andamento pode ser substituída.`,[
 {label:'Cancelar'}, {label:'Importar prova antiga',style:'',action:()=>{const mapped={...ex,flagged:ex.flagged||[],pos:Math.max(0,Math.min(ex.pos||0,ex.ids.length-1)),startedAt:ex.startedAt||ex.start||Date.now(),label:'Prova antiga recuperada',origin:'legacy',timed:false};state.exam=mapped;state.seenIds=unique([...(state.seenIds||[]),...mapped.ids]);persist();go('exam');}}
 ]);
}
function menuClick(e){let filter=e.target.closest('[data-map-filter]');if(filter){mapFilter=filter.dataset.mapFilter;const open=document.body.classList.contains('exam-map-open');renderExam();document.body.classList.toggle('exam-map-open',open);$('#exam-map-panel')?.querySelector('[data-map-filter="'+mapFilter+'"]')?.focus();return}let item=e.target.closest('[data-act],[data-nav],[data-position],[data-result]');if(!item)return;if(item.hasAttribute('data-nav')){e.preventDefault();go(item.dataset.nav);return}if(item.hasAttribute('data-position')){moveQuestion(Number(item.dataset.position));return}if(item.hasAttribute('data-result')){state.lastResultId=item.dataset.result;go('result');return}
 const action=item.dataset.act;
 if(action==='save-status'){modal('Estado do salvamento',storageNote+' · Última gravação confirmada: '+(lastSavedAt?new Date(lastSavedAt).toLocaleTimeString('pt-BR'):'não confirmada')+'. Você pode fazer uma cópia JSON para maior segurança.',[{label:'Fechar'},{label:'Baixar backup',style:'',action:exportBackup}]);return}
 if(action==='setup')go('setup');else if(action==='resume')go('exam');else if(action==='start')startExam();else if(action==='prev')moveQuestion(state.exam.pos-1);else if(action==='next')moveQuestion(state.exam.pos+1);else if(action==='flag'){let ex=state.exam,id=ex.ids[ex.pos];ex.flagged=ex.flagged.includes(id)?ex.flagged.filter(x=>x!==id):[...ex.flagged,id];persist();renderExam()}
 else if(action==='jump-pending'){const ex=state.exam;if(!ex)return;const n=ex.ids.length;let target=-1;for(let k=1;k<=n;k++){const at=(ex.pos+k)%n;if(!Number.isInteger(ex.answers[ex.ids[at]])){target=at;break}}if(target>=0)moveQuestion(target);else notice('Todas as questões foram respondidas.')}
 else if(action==='toggle-map'){const open=!document.body.classList.contains('exam-map-open');document.body.classList.toggle('exam-map-open',open);const b=$('[data-act=toggle-map][aria-expanded]');if(b)b.setAttribute('aria-expanded',String(open));return}
 else if(action==='font-toggle'){state.preferences=state.preferences||{};state.preferences.examLarge=!state.preferences.examLarge;document.body.classList.toggle('exam-large',state.preferences.examLarge);persist();return}
 else if(action==='map-filter'){return}
 else if(action==='recover-import-exam'){const i=Number(item.dataset.examImport),chosen=state.savedExams?.[i]?.exam;if(!chosen){notice('Cópia da prova não encontrada.','bad');return}if(state.exam){modal('Substituir a prova em andamento?', 'Uma cópia da sua prova atual será baixada antes de retomar a importada.',[{label:'Cancelar'},{label:'Baixar cópia e retomar',style:'',action:()=>{exportBackup();state.savedExams.push({exam:state.exam,importedAt:Date.now()});state.exam=chosen;persist();go('exam')}}]);return}state.exam=chosen;persist();go('exam');return}
 else if(action==='recover-draft'){const d=state.essay?.importedDrafts?.[Number(item.dataset.draftIndex)];if(!d)return;modal('Restaurar rascunho importado?', 'Seu texto atual será preservado na lista de importados, antes de restaurar o selecionado.',[{label:'Cancelar'},{label:'Restaurar texto',style:'',action:()=>{const old=state.essay.text;if(old&&old!==d.text)state.essay.importedDrafts.push({text:old,notes:state.essay.notes||'',importedAt:Date.now()});state.essay.text=d.text;state.essay.notes=d.notes||'';persist();go('essay')}}]);return}
 else if(action==='sync-tab'){exportBackup();restore();go(state.exam?'exam':'home');notice('Dados mais recentes carregados após criar uma cópia de segurança.','good');return}
 else if(action==='jump-number'){const num=Number($('#q-jump-number')?.value);if(Number.isInteger(num)&&num>=1&&num<=state.exam.ids.length)moveQuestion(num-1);else notice('Digite um número válido.','warn')}
 else if(action==='clear-choice'){delete state.exam.answers[state.exam.ids[state.exam.pos]];persist();renderExam()}
 else if(action==='finish')finishPrompt();else if(action==='backup')exportBackup();else if(action==='recover-legacy')recoverLegacy();else if(action==='essay-export')download('minha_redacao_enem.txt',state.essay.text||'','text/plain');
}
function mainChange(e){let t=e.target;
 if(t.dataset.choice!==undefined){pickAnswer(Number(t.dataset.choice));return}
 const mapping={'cfg-mode':['mode',String],'cfg-area':['area',String],'cfg-subject':['subject',String],'cfg-topic':['topic',String],'cfg-count':['count',Number],'cfg-language':['language',String],'cfg-time-mode':['timed',x=>x==='countdown'],'cfg-minutes':['minutes',Number]};
 if(mapping[t.id]){const [key,cast]=mapping[t.id];state.config[key]=cast(t.type==='checkbox'?t.checked:t.value);
 if(key==='mode'&&state.config.mode==='area'&&state.config.area==='Todas')state.config.area='Linguagens';
 if(key==='mode'&&state.config.mode==='subject'&&state.config.subject==='Todas')state.config.subject='Português';
 if(key==='mode'&&state.config.mode==='topic'&&state.config.topic==='Todos')state.config.topic='Interpretação de textos';
 if(key==='count'&&!COUNTS.includes(state.config.count))state.config.count=10;if(key==='minutes')state.config.minutes=Math.min(360,Math.max(1,state.config.minutes||90));persist();if(key==='mode')renderSetup();else if(['area','subject','topic','language','timed','minutes','count'].includes(key))setupVisibility();return}
 if(t.id==='import-file'&&t.files?.[0]){const file=t.files[0];if(file.size>20*1024*1024){notice('Backup maior que 20 MB. Preserve o arquivo original e solicite importação assistida.','bad');return}file.text().then(text=>{let data;try{data=validateImported(JSON.parse(text))}catch(err){notice('Não foi possível ler o arquivo: '+err.message,'bad');return}modal('Como deseja importar?',`Arquivo ${file.name} validado. A mesclagem preserva sua prova atual e combina os históricos. A substituição troca os dados existentes. Em ambos os casos, o sistema baixa automaticamente um backup antes de alterar.`,[{label:'Cancelar'},{label:'Mesclar dados',style:'',action:()=>{try{applyImport(data,'merge')}catch(err){notice(err.message,'bad')}}},{label:'Substituir após backup',style:'secondary',action:()=>{try{applyImport(data,'replace')}catch(err){notice(err.message,'bad')}}}])}).catch(err=>notice('Falha na leitura: '+err.message,'bad'))}
}
function mainInput(e){if(e.target.id==='essay-text'){state.essay.text=e.target.value;persist();$('#word-count').textContent=(state.essay.text.trim()?state.essay.text.trim().split(/\s+/).length:0)+' palavras • salvo automaticamente'}else if(e.target.id==='essay-notes'){state.essay.notes=e.target.value;persist()}}
function init(){document.addEventListener('keydown',e=>{if(route==='exam'&&state.exam&&$('#dialog-root')?.classList.contains('hidden')&&!e.altKey&&!e.ctrlKey&&!e.metaKey&&!e.repeat&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.activeElement?.isContentEditable){const k=e.key.toLowerCase();if('abcde'.includes(k)&&k.length===1){pickAnswer('abcde'.indexOf(k));e.preventDefault();return}if(k==='arrowright'){moveQuestion(state.exam.pos+1);e.preventDefault();return}if(k==='arrowleft'){moveQuestion(state.exam.pos-1);e.preventDefault();return}if(k==='r'){const id=state.exam.ids[state.exam.pos];state.exam.flagged=state.exam.flagged.includes(id)?state.exam.flagged.filter(x=>x!==id):[...state.exam.flagged,id];persist();renderExam();e.preventDefault();return}}const root=$('#dialog-root');if(!root.classList.contains('hidden')){if(e.key==='Escape'){root.querySelector('#modal-actions button')?.click();e.preventDefault();return}if(e.key==='Tab'){const buttons=[...root.querySelectorAll('button')];if(!buttons.length)return;let at=buttons.indexOf(document.activeElement);if(e.shiftKey&&at<=0){buttons.at(-1).focus();e.preventDefault()}else if(!e.shiftKey&&at===buttons.length-1){buttons[0].focus();e.preventDefault()}}}else if(e.key==='Escape'&&document.body.classList.contains('exam-map-open'))document.body.classList.remove('exam-map-open')});if(validQuestions.length!==NEW.length){console.error('Banco com itens inválidos. Foram removidos:',NEW.length-validQuestions.length)};
 restore();document.addEventListener('click',menuClick);document.addEventListener('change',mainChange);document.addEventListener('input',mainInput);
 $('#mobile-more')?.addEventListener('click',()=>{let nav=$('#side-nav');let next=!nav.classList.contains('open');nav.classList.toggle('open',next);document.body.classList.toggle('nav-is-open',next);$('#mobile-more').setAttribute('aria-expanded',String(next));$('#menu-btn').setAttribute('aria-expanded',String(next))});$('#nav-shade')?.addEventListener('click',()=>{document.body.classList.remove('nav-is-open');$('#side-nav').classList.remove('open');$('#mobile-more')?.setAttribute('aria-expanded','false')});
 $('#theme-btn').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;persist()});$('#menu-btn').addEventListener('click',()=>{let nav=$('#side-nav');let next=!nav.classList.contains('open');nav.classList.toggle('open',next);$('#menu-btn').setAttribute('aria-expanded',String(next))});
 window.addEventListener('beforeunload',()=>{persist()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')persist();else if(state.exam?.timed&&remaining(state.exam)<=0)finishExam('tempo encerrado')});
 window.addEventListener('storage',e=>{if(e.key===STORE){pendingExternal=true;storageMode='conflict';storageNote='Alterações em outra aba — esta aba não sobrescreverá os dados';setPill();const slot=$('#alert-slot');if(slot)slot.innerHTML='<div class="notice warn" role="alert"><strong>Outra aba atualizou seus estudos.</strong> Esta aba não irá substituir os dados mais recentes. <div class="btnrow"><button class="button secondary" data-act="backup">Baixar cópia desta aba</button><button class="button" data-act="sync-tab">Carregar dados atualizados</button></div></div>'}});
 window.addEventListener('error',e=>{console.error('Falha da plataforma',e.error||e.message);notice('Ocorreu um erro. Suas respostas já registradas não foram apagadas. Exporte um backup.','bad')});
 go(state.exam?'exam':'home');
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
window.ENEM_BRIDGE={
 get:()=>state,
 save:()=>persist(),
 patchMentor:updater=>{const base=state.mentor&&typeof state.mentor==='object'?state.mentor:{version:1};state.mentor=typeof updater==='function'?updater(base):{...base,...updater};persist();return state.mentor},
 go,notice,modal,
 getBank:()=>NEW.slice(),
 getLegacy:()=>LEGACY.slice(),
 startTopic:(topic)=>{if(state.exam){notice('Há uma prova em andamento. Finalize ou retome-a antes de iniciar outra.');go('exam');return;}const free=unseenFor({...defaultCfg(),mode:'topic',topic});if(!free.length){notice('Ainda não há questões inéditas para este assunto.','warn');return;}state.config={...defaultCfg(),mode:'topic',topic,count:Math.min(5,free.length)};persist();startExam(true)},
 startErrorReview:()=>{if(state.exam){go('exam');return}state.config={...defaultCfg(),mode:'errors',count:Math.min(10,unseenFor({...defaultCfg(),mode:'errors'}).length||1)};persist();startExam(true)},
 startRetest:()=>{if(state.exam){go('exam');return}const miss=new Set(state.history.flatMap(h=>h.rows||[]).filter(r=>r.status==='wrong').map(r=>r.topic));const used=new Set(state.history.flatMap(h=>h.ids||[]));let fresh=NEW.filter(q=>miss.has(q.topic)&&!used.has(q.id));if(!fresh.length){notice('Ainda não há questões inéditas para os assuntos errados. Use o modo de refazer questões sem tratar a repetição como uma nova medida de domínio.');return}state.config={...defaultCfg(),mode:'targeted',ids:fresh.map(q=>q.id),count:Math.min(10,fresh.length)};persist();startExam(true)},
 exportBackup,
};
window.ENEM_TEST={getState:()=>JSON.parse(JSON.stringify(state)),startExam,finishExam,pickAnswer,restore,calc,availableFor,getBank:()=>NEW,getSeen:()=>[...(state.seenIds||[])],unseenFor,selection,applyImport};
})();
